INSERT INTO public.testimonials (id, name, role, text, stars, avatar_bg) VALUES
('1', 'Marina Santos', 'Cliente há 3 anos', 'Simplesmente a melhor experiência que já tive em uma clínica. O atendimento é impecável e os resultados do Botox foram super naturais, exatamente como eu queria.', 5, 'bg-secondary-fixed-dim text-secondary'),
('2', 'Fernanda Lima', 'Cliente há 1 ano', 'Fiz o pacote de corporal (Velashape) e estou encantada. A equipe é muito capacitada e o ambiente é muito relaxante. Vale cada centavo!', 5, 'bg-primary-fixed text-primary'),
('3', 'Camila Oliveira', 'Cliente Nova', 'A limpeza de pele mais completa que já fiz. Saí com a pele iluminada e me sentindo super cuidada. Recomendo de olhos fechados!', 5, 'bg-tertiary-fixed text-tertiary')
INSERT INTO public.faqs (id, question, answer) VALUES
('faq-1', 'Os procedimentos são doloridos?', 'A maioria dos nossos procedimentos são minimamente invasivos e causam apenas um leve desconforto. Utilizamos anestésicos tópicos de alta qualidade sempre que necessário para garantir sua total comodidade.'),
('faq-2', 'Quanto tempo dura o efeito do Botox?', 'Em média, os resultados da toxina botulínica duram entre 4 a 6 meses, variando de acordo com o organismo de cada paciente e seus hábitos de vida.'),
('faq-3', 'Como funciona o agendamento?', 'Você pode agendar sua avaliação clicando no botão "Agendar Consulta" em nosso menu ou através do nosso WhatsApp. Realizamos uma consulta prévia para entender suas necessidades e indicar o melhor protocolo.')
INSERT INTO public.blog_posts (id, title, slug, category, author, date, read_time, featured, image, excerpt, content) VALUES
('post-1', 'Bioestimuladores de Colágeno: O Segredo do Rejuvenescimento Natural', 'bioestimuladores-de-colageno-guia', 'Tratamentos Faciais', 'Dra. Camila Vasconcelos', '24 de Julho, 2026', '5 min de leitura', true, 'https://images.unsplash.com/photo-1570172619644-dfd03ed5d881?auto=format&fit=crop&w=800&q=80', 'Descubra como os bioestimuladores acionam a produção natural de colágeno pelo próprio organismo, devolvendo firmeza e viço sem alterar seus traços.', 'Os bioestimuladores de colágeno revolucionaram a dermatologia estética avançada ao oferecer um rejuvenescimento gradual, seguro e extremamente natural. Diferente dos preenchedores tradicionais que apenas conferem volume imediato, substâncias como o ácido poli-L-láctico e a hidroxiapatita de cálcio estimulam as células do próprio corpo a produzirem novas fibras de colágeno.'),
('post-2', 'Cuidados Essenciais com a Pele Pós-Procedimento Estético', 'cuidados-pos-procedimento-estetico', 'Skincare & Dicas', 'Dr. Lucas Ribeiro', '18 de Julho, 2026', '4 min de leitura', true, 'https://images.unsplash.com/photo-1512290900676-26c2a48f4134?auto=format&fit=crop&w=800&q=80', 'Saiba o que fazer e o que evitar logo após sessões de Botox, Peeling ou Ultraformer para maximizar seus resultados com segurança.', 'Realizar um procedimento estético é apenas metade da jornada para alcançar a pele dos seus sonhos. Os cuidados domiciliares pós-procedimento desempenham um papel crucial na otimização dos resultados e na prevenção de reações indesejadas.'),
('post-3', 'Ultraformer III vs. Preenchimento: Qual o Melhor para Flacidez?', 'ultraformer-vs-preenchimento', 'Tecnologias Avançadas', 'Dra. Camila Vasconcelos', '10 de Julho, 2026', '6 min de leitura', false, 'https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?auto=format&fit=crop&w=800&q=80', 'Entenda a diferença entre ultrassom microfocado e ácido hialurônico para escolher a abordagem perfeita para o seu rosto.', 'Uma das dúvidas mais frequentes na clínica é se o melhor caminho para tratar a queda do contorno facial é o Ultraformer III ou o preenchimento com ácido hialurônico. A resposta curta é: eles possuem indicações distintas e frequentemente se complementam!')
